// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra;

import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;

import java.util.List;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.junit.jupiter.api.Test;

class ProjectionSourceExpressionCloneOwnershipTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void queryRootCloneRebindsSharedProjectionSourceExpressionToOwnedExtension() {
		ExtensionElem shared = new ExtensionElem(new ValueConstant(VF.createLiteral("owned")), "value");
		Extension extension = new Extension(new SingletonSet(), shared);
		ProjectionElem first = new ProjectionElem("value", "first");
		ProjectionElem second = new ProjectionElem("value", "second");
		first.setSourceExpression(shared);
		second.setSourceExpression(shared);
		QueryRoot source = new QueryRoot(
				new Projection(extension, new ProjectionElemList(first, second)));

		QueryRoot cloned = source.clone();
		Projection clonedProjection = (Projection) cloned.getArg();
		Extension clonedExtension = (Extension) clonedProjection.getArg();
		ExtensionElem clonedOwnedExpression = clonedExtension.getElements().get(0);
		List<ProjectionElem> clonedElements = clonedProjection.getProjectionElemList().getElements();

		assertNotSame(source, cloned);
		assertNotSame(shared, clonedOwnedExpression);
		assertSame(clonedOwnedExpression, clonedElements.get(0).getSourceExpression());
		assertSame(clonedOwnedExpression, clonedElements.get(1).getSourceExpression());
	}

	@Test
	void queryRootCloneRebindsSharedMultiProjectionSourceExpressionToOwnedExtension() {
		ExtensionElem shared = new ExtensionElem(new ValueConstant(VF.createLiteral("owned")), "value");
		Extension extension = new Extension(new SingletonSet(), shared);
		ProjectionElem first = new ProjectionElem("value", "first");
		ProjectionElem second = new ProjectionElem("value", "second");
		first.setSourceExpression(shared);
		second.setSourceExpression(shared);
		MultiProjection source = new MultiProjection(extension,
				List.of(new ProjectionElemList(first), new ProjectionElemList(second)));

		QueryRoot cloned = new QueryRoot(source).clone();
		MultiProjection clonedProjection = (MultiProjection) cloned.getArg();
		Extension clonedExtension = (Extension) clonedProjection.getArg();
		ExtensionElem clonedOwnedExpression = clonedExtension.getElements().get(0);
		ProjectionElem clonedFirst = clonedProjection.getProjections().get(0).getElements().get(0);
		ProjectionElem clonedSecond = clonedProjection.getProjections().get(1).getElements().get(0);

		assertNotSame(shared, clonedOwnedExpression);
		assertSame(clonedOwnedExpression, clonedFirst.getSourceExpression());
		assertSame(clonedOwnedExpression, clonedSecond.getSourceExpression());
	}

	@Test
	void queryRootCloneKeepsUnparentedAndExternalProjectionSourceExpressionsExternal() {
		ExtensionElem unparented = new ExtensionElem(new ValueConstant(VF.createLiteral("free")), "free");
		ProjectionElem freeProjectionElem = new ProjectionElem("free");
		freeProjectionElem.setSourceExpression(unparented);
		QueryRoot freeSource = new QueryRoot(
				new Projection(new SingletonSet(), new ProjectionElemList(freeProjectionElem)));

		QueryRoot freeClone = freeSource.clone();
		ProjectionElem clonedFreeElem = ((Projection) freeClone.getArg()).getProjectionElemList().getElements().get(0);
		assertSame(unparented, clonedFreeElem.getSourceExpression());
		assertNull(unparented.getParentNode());

		ExtensionElem external = new ExtensionElem(new ValueConstant(VF.createLiteral("outside")), "outside");
		Extension externalOwner = new Extension(new SingletonSet(), external);
		ProjectionElem externalProjectionElem = new ProjectionElem("outside");
		externalProjectionElem.setSourceExpression(external);
		QueryRoot externalSource = new QueryRoot(
				new Projection(new SingletonSet(), new ProjectionElemList(externalProjectionElem)));

		QueryRoot externalClone = externalSource.clone();
		ProjectionElem clonedExternalElem = ((Projection) externalClone.getArg()).getProjectionElemList()
				.getElements()
				.get(0);
		assertSame(external, clonedExternalElem.getSourceExpression());
		assertSame(externalOwner, clonedExternalElem.getSourceExpression().getParentNode());
	}
}
